"""
Transcript parsers for the Agents service.

Pluggable parser registry with @register_parser decorator.
Each parser converts tool-specific transcript formats into
normalized TranscriptEntry objects.
"""

import json
import logging
import time
import uuid
from pathlib import Path
from typing import Any, Callable, Generator, Optional

from .constants import TRANSCRIPT_INITIAL_ENTRIES, TRANSCRIPT_POLL_INTERVAL_S
from .schemas import AgentStatus, TranscriptEntry

logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Parser registry
# ---------------------------------------------------------------------------

_PARSERS: dict[str, Callable] = {}


def register_parser(format_name: str):
    """Decorator to register a transcript parser.

    Args:
        format_name: Identifier for the transcript format
            (e.g. "claude_jsonl", "opencode_sse", "codex_jsonl").

    Example::

        @register_parser("claude_jsonl")
        def parse_claude(raw_entry: dict) -> list[TranscriptEntry] | None:
            ...
    """

    def decorator(fn: Callable) -> Callable:
        _PARSERS[format_name] = fn
        return fn

    return decorator


def parse_transcript(
    format_name: str,
    source: str,
    max_entries: int = 200,
) -> list[TranscriptEntry]:
    """Parse a transcript file using the registered parser.

    Args:
        format_name: Which parser to use.
        source: Path to the transcript file.
        max_entries: Maximum entries to return.

    Returns:
        List of parsed TranscriptEntry objects.
    """
    parser = _PARSERS.get(format_name)
    if parser is None:
        logger.warning("No parser registered for format: %s", format_name)
        return []

    path = Path(source)
    if not path.exists():
        return []

    entries: list[TranscriptEntry] = []
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    raw = json.loads(line)
                except json.JSONDecodeError:
                    continue
                result = parser(raw)
                if result is None:
                    continue
                if isinstance(result, list):
                    entries.extend(result)
                else:
                    entries.append(result)
                if len(entries) >= max_entries:
                    break
    except Exception as e:
        logger.debug("Error parsing transcript %s: %s", source, e)

    return entries[-max_entries:]


def detect_status_from_transcript(
    entries: list[TranscriptEntry],
    idle_threshold_s: float = 60.0,
) -> AgentStatus:
    """Detect agent status from parsed transcript entries.

    Args:
        entries: Parsed transcript entries (most recent last).
        idle_threshold_s: Seconds since last entry before marking idle.

    Returns:
        AgentStatus based on transcript activity.
    """
    if not entries:
        return AgentStatus.IDLE

    last = entries[-1]
    now = time.time()

    if last.timestamp and (now - last.timestamp) > idle_threshold_s:
        return AgentStatus.IDLE

    if last.type == "status_change":
        content = last.content.lower()
        if content in ("busy", "working"):
            return AgentStatus.WORKING
        if content in ("idle",):
            return AgentStatus.IDLE
        if content in ("waiting", "retry"):
            return AgentStatus.WAITING

    if last.type in ("assistant_text", "tool_call", "thinking"):
        return AgentStatus.WORKING
    if last.type in ("user_message", "user_text"):
        return AgentStatus.WORKING
    if last.type in ("turn_end",):
        return AgentStatus.IDLE
    return AgentStatus.IDLE


# ---------------------------------------------------------------------------
# File tail utilities
# ---------------------------------------------------------------------------


def read_recent_entries(
    path: Path,
    n: int = 20,
    parser_name: Optional[str] = None,
) -> list[TranscriptEntry]:
    """Read the last N meaningful entries from a transcript file.

    Args:
        path: Path to the transcript file.
        n: Number of entries to return.
        parser_name: Parser to use. If None, returns raw dicts
            wrapped as TranscriptEntry.

    Returns:
        List of TranscriptEntry objects.
    """
    parser = _PARSERS.get(parser_name) if parser_name else None
    events: list[TranscriptEntry] = []

    try:
        with open(path, "rb") as f:
            f.seek(0, 2)
            file_size = f.tell()
            if file_size == 0:
                return events
            chunk_size = min(file_size, 16384 * n)
            f.seek(file_size - chunk_size)
            data = f.read().decode("utf-8", errors="replace")

        lines = [l for l in data.strip().split("\n") if l.strip()]
        # Take extra lines to account for multi-event entries
        for line in lines[-(n * 3) :]:
            try:
                entry = json.loads(line)
            except json.JSONDecodeError:
                continue

            if parser:
                result = parser(entry)
                if result is None:
                    continue
                if isinstance(result, list):
                    events.extend(result)
                else:
                    events.append(result)
            else:
                events.append(TranscriptEntry(**entry))

        return events[-n:]
    except Exception as e:
        logger.debug("Error reading recent transcript entries from %s: %s", path, e)
        return events


def read_new_entries(
    path: Path,
    offset: int,
    parser_name: Optional[str] = None,
) -> list[TranscriptEntry]:
    """Read new entries added after the given byte offset.

    Args:
        path: Path to the transcript file.
        offset: Byte offset to start reading from.
        parser_name: Parser to use.

    Returns:
        List of new TranscriptEntry objects.
    """
    parser = _PARSERS.get(parser_name) if parser_name else None
    events: list[TranscriptEntry] = []

    try:
        with open(path, "rb") as f:
            f.seek(offset)
            data = f.read().decode("utf-8", errors="replace")

        for line in data.strip().split("\n"):
            line = line.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
            except json.JSONDecodeError:
                continue

            if parser:
                result = parser(entry)
                if result is None:
                    continue
                if isinstance(result, list):
                    events.extend(result)
                else:
                    events.append(result)
            else:
                events.append(TranscriptEntry(**entry))
    except Exception as e:
        logger.debug("Error reading new transcript entries from %s: %s", path, e)

    return events


# ===========================================================================
# Concrete parsers
# ===========================================================================


@register_parser("claude_jsonl")
def _parse_claude_entry(entry: dict) -> Optional[list[TranscriptEntry]]:
    """Parse a Claude Code JSONL transcript entry.

    Claude transcript format:
      - type=assistant: message.content = [{type: text|tool_use|thinking, ...}]
      - type=user: message.content = string | [{type: tool_result, ...}]
      - type=system, subtype=turn_duration: turn timing info
    """
    entry_type = entry.get("type", "")
    timestamp = entry.get("timestamp", "")

    if entry_type == "assistant":
        message = entry.get("message", {})
        content_blocks = message.get("content", [])
        model = message.get("model", "")

        events = []
        for block in content_blocks:
            block_type = block.get("type", "")
            if block_type == "text":
                events.append(
                    TranscriptEntry(
                        id=str(uuid.uuid4()),
                        type="assistant_text",
                        content=block.get("text", ""),
                        timestamp=_parse_ts(timestamp),
                        model=model,
                    )
                )
            elif block_type == "tool_use":
                tool_input = block.get("input", {})
                tool_name = block.get("name", "unknown")
                # Summarize tool input
                summary = ""
                if tool_name in ("Read", "Glob", "Grep"):
                    summary = (
                        tool_input.get("file_path")
                        or tool_input.get("pattern")
                        or tool_input.get("path", "")
                    )
                elif tool_name == "Bash":
                    summary = tool_input.get("command", "")[:200]
                elif tool_name in ("Edit", "Write"):
                    summary = tool_input.get("file_path", "")
                else:
                    summary = json.dumps(tool_input)[:150]

                events.append(
                    TranscriptEntry(
                        id=str(uuid.uuid4()),
                        type="tool_call",
                        content=summary,
                        tool_name=tool_name,
                        tool_id=block.get("id", ""),
                        timestamp=_parse_ts(timestamp),
                    )
                )
            elif block_type == "thinking":
                events.append(
                    TranscriptEntry(
                        id=str(uuid.uuid4()),
                        type="thinking",
                        content=block.get("thinking", "")[:200],
                        timestamp=_parse_ts(timestamp),
                    )
                )

        return events if events else None

    if entry_type == "user":
        message = entry.get("message", {})
        content = message.get("content", "")

        if isinstance(content, str):
            return [
                TranscriptEntry(
                    id=str(uuid.uuid4()),
                    type="user_message",
                    content=content,
                    timestamp=_parse_ts(timestamp),
                )
            ]
        if isinstance(content, list):
            events = []
            for block in content:
                if block.get("type") == "tool_result":
                    raw_content = block.get("content", "")
                    if isinstance(raw_content, list):
                        texts = [b.get("text", "") for b in raw_content if b.get("type") == "text"]
                        result_content = "\n".join(texts)
                    else:
                        result_content = raw_content
                    events.append(
                        TranscriptEntry(
                            id=str(uuid.uuid4()),
                            type="tool_result",
                            content=str(result_content),
                            tool_id=block.get("tool_use_id", ""),
                            timestamp=_parse_ts(timestamp),
                        )
                    )
            return events if events else None

    if entry_type == "system":
        subtype = entry.get("subtype", "")
        if subtype == "turn_duration":
            duration_ms = entry.get("durationMs", 0)
            return [
                TranscriptEntry(
                    id=str(uuid.uuid4()),
                    type="turn_end",
                    content=f"Turn completed in {duration_ms / 1000:.1f}s",
                    timestamp=_parse_ts(timestamp),
                )
            ]

    return None


@register_parser("opencode_sse")
def _parse_opencode_event(raw_event: str) -> Optional[TranscriptEntry]:
    """Normalize an OpenCode SSE event to TranscriptEntry.

    OpenCode v1.2.x event structure:
      {"type": "<event_type>", "properties": { ... }}

    Accepts either a raw SSE string (data: {...}) or a pre-parsed dict.
    """
    # Handle both raw SSE string and pre-parsed dict
    if isinstance(raw_event, str):
        data_lines = []
        for line in raw_event.strip().split("\n"):
            if line.startswith("data: "):
                data_lines.append(line[6:])
            elif line.startswith("data:"):
                data_lines.append(line[5:])
        if not data_lines:
            return None
        try:
            payload = json.loads("".join(data_lines))
        except json.JSONDecodeError:
            return None
    elif isinstance(raw_event, dict):
        payload = raw_event
    else:
        return None

    event_type = payload.get("type", "")
    props = payload.get("properties", {})
    ts = time.time()

    if event_type == "message.part.updated":
        part = props.get("part", {})
        if not isinstance(part, dict):
            return None
        part_type = part.get("type", "")
        part_id = part.get("id", str(uuid.uuid4()))
        part_time = part.get("time", {})
        part_ts = (
            part_time.get("start", part_time.get("end", ts)) if isinstance(part_time, dict) else ts
        )
        if isinstance(part_ts, (int, float)) and part_ts > 1e12:
            part_ts = part_ts / 1000.0

        if part_type == "text":
            text = part.get("text", "")
            if not text:
                return None
            return TranscriptEntry(
                id=part_id,
                type="assistant_text",
                timestamp=part_ts,
                content=text,
            )
        if part_type == "reasoning":
            text = part.get("text", "")
            if not text:
                return None
            return TranscriptEntry(
                id=part_id,
                type="thinking",
                timestamp=part_ts,
                content=text,
            )
        if part_type == "tool-invocation":
            raw_input = part.get("input", part.get("args", ""))
            content = json.dumps(raw_input) if isinstance(raw_input, dict) else str(raw_input)
            return TranscriptEntry(
                id=part_id,
                type="tool_call",
                timestamp=part_ts,
                content=content,
                tool_name=part.get("toolName", part.get("name", "")),
            )
        if part_type == "tool-result":
            return TranscriptEntry(
                id=part_id,
                type="tool_result",
                timestamp=part_ts,
                content=part.get("result", part.get("output", "")),
                tool_name=part.get("toolName", part.get("name", "")),
                tool_success=not part.get("isError", False),
            )
        if part_type in ("step-start", "step-finish"):
            return None

    if event_type == "message.updated":
        info = props.get("info", {})
        role = info.get("role", "")
        if role == "assistant" and info.get("time", {}).get("completed"):
            model = info.get("modelID", "")
            cost = info.get("cost", 0)
            return TranscriptEntry(
                id=info.get("id", str(uuid.uuid4())),
                type="turn_end",
                timestamp=info.get("time", {}).get("completed", ts),
                content=f"model={model} cost={cost}",
                model=model,
            )
        return None

    if event_type == "session.status":
        status_obj = props.get("status", {})
        status_type = (
            status_obj.get("type", "") if isinstance(status_obj, dict) else str(status_obj)
        )
        return TranscriptEntry(
            id=str(uuid.uuid4()),
            type="status_change",
            timestamp=ts,
            content=status_type,
        )

    return None


@register_parser("codex_jsonl")
def _parse_codex_entry(entry: dict) -> Optional[TranscriptEntry]:
    """Parse a Codex JSONL entry into a TranscriptEntry.

    Codex rollout format (v0.101+):
      - type=response_item: Full message snapshots (skipped to avoid duplicates)
      - type=event_msg: Streaming events with payload.type
    """
    entry_type = entry.get("type", "")
    ts = entry.get("timestamp", time.time())
    payload = entry.get("payload", {})
    event_id = str(uuid.uuid4())

    # Skip response_item — event_msg provides the same content with better
    # granularity and timing.
    if entry_type == "response_item":
        return None

    if entry_type == "event_msg":
        evt_type = payload.get("type", "")

        if evt_type == "agent_message":
            msg = payload.get("message", "")
            if not msg:
                return None
            return TranscriptEntry(
                id=event_id,
                type="assistant_text",
                timestamp=ts,
                content=msg,
            )
        if evt_type == "agent_reasoning":
            msg = payload.get("message", "")
            if not msg:
                return None
            return TranscriptEntry(
                id=event_id,
                type="thinking",
                timestamp=ts,
                content=msg,
            )
        if evt_type == "user_message":
            msg = payload.get("message", "")
            if not msg:
                return None
            return TranscriptEntry(
                id=event_id,
                type="user_text",
                timestamp=ts,
                content=msg[:500],
            )
        if evt_type == "exec_command":
            cmd = payload.get("command", payload.get("call_id", ""))
            return TranscriptEntry(
                id=event_id,
                type="tool_call",
                timestamp=ts,
                content=cmd if isinstance(cmd, str) else json.dumps(cmd),
                tool_name="shell",
            )
        if evt_type == "exec_command_completed":
            output = payload.get("stdout", payload.get("output", ""))
            return TranscriptEntry(
                id=event_id,
                type="tool_result",
                timestamp=ts,
                content=(output[:500] if isinstance(output, str) else str(output)[:500]),
                tool_name="shell",
                tool_success=payload.get("exit_code", 0) == 0,
            )
        if evt_type == "tool_call":
            return TranscriptEntry(
                id=event_id,
                type="tool_call",
                timestamp=ts,
                content=payload.get("arguments", payload.get("input", "")),
                tool_name=payload.get("name", "unknown"),
            )
        if evt_type == "tool_call_output":
            return TranscriptEntry(
                id=event_id,
                type="tool_result",
                timestamp=ts,
                content=payload.get("output", ""),
                tool_name=payload.get("name", ""),
                tool_success=not payload.get("error", False),
            )
        if evt_type == "task_started":
            return TranscriptEntry(
                id=event_id,
                type="status_change",
                timestamp=ts,
                content="busy",
            )
        if evt_type == "task_complete":
            return TranscriptEntry(
                id=event_id,
                type="status_change",
                timestamp=ts,
                content="idle",
            )

    return None


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _parse_ts(value: Any) -> Optional[float]:
    """Convert a timestamp value to float seconds, or None."""
    if value is None or value == "":
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            pass
        # Try ISO format
        try:
            from datetime import datetime

            dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
            return dt.timestamp()
        except (ValueError, TypeError):
            pass
    return None


# ---------------------------------------------------------------------------
# Tool-to-parser mapping
# ---------------------------------------------------------------------------


def get_parser_for_tool(tool: str) -> Optional[str]:
    """Map tool identifier to transcript parser name."""
    tool_parser_map = {
        "claude": "claude_jsonl",
        "codex": "codex_jsonl",
        "codeq": "opencode_sse",
    }
    return tool_parser_map.get(tool)


# ---------------------------------------------------------------------------
# Live transcript watcher
# ---------------------------------------------------------------------------


def watch_transcript(
    path: Path,
    parser_name: Optional[str] = None,
    poll_interval: float = TRANSCRIPT_POLL_INTERVAL_S,
    initial_entries: int = TRANSCRIPT_INITIAL_ENTRIES,
) -> Generator[TranscriptEntry, None, None]:
    """Yield new transcript entries as they appear.

    Starts by yielding the last ``initial_entries`` entries, then polls
    for new entries every ``poll_interval`` seconds.

    This generator runs indefinitely until the caller breaks or the
    file is deleted.
    """
    # Yield initial history
    yield from read_recent_entries(path, n=initial_entries, parser_name=parser_name)

    # Start tailing from the current end of file
    offset = path.stat().st_size

    while True:
        time.sleep(poll_interval)

        if not path.exists():
            return

        new_entries = read_new_entries(path, offset, parser_name=parser_name)
        yield from new_entries

        offset = path.stat().st_size
